// Provides configurable retry with linear or exponential backoff.
//
// Quickest path — let Do run the loop:
//
//	cfg := retry.New() |> retry.Attempts(5) |> retry.Delay(500 * time.Millisecond)
//	    |> retry.MaxDelay(5 * time.Second) |> retry.Jitter(0.2)
//	err := retry.Do(cfg, () =>
//	    _, err := fetch.Get(url)
//	    return err
