package retry

import (
	"fmt"
	ctxpkg "kukicha.org/kukicha/stdlib/ctx"
	"kukicha.org/kukicha/stdlib/datetime"
	"kukicha.org/kukicha/stdlib/math"
	"kukicha.org/kukicha/stdlib/random"
	"time"
)

// Strategy selects how the delay between attempts grows.
// Linear reuses InitialDelay every attempt; Exponential doubles it.
type Strategy string

const (
	StrategyLinear      Strategy = "linear"
	StrategyExponential Strategy = "exponential"
)

func AllStrategy() []Strategy {
	return []Strategy{StrategyLinear, StrategyExponential}
}

func ParseStrategy(s string) (Strategy, error) {
	switch s {
	case "linear":
		return StrategyLinear, nil
	case "exponential":
		return StrategyExponential, nil
	}
	switch s {
	case "Linear":
		return StrategyLinear, nil
	case "Exponential":
		return StrategyExponential, nil
	}
	var zero Strategy
	return zero, fmt.Errorf("invalid Strategy %q (valid: \"linear\", \"exponential\")", s)
}

func (e Strategy) String() string {
	switch e {
	case StrategyLinear:
		return "Linear"
	case StrategyExponential:
		return "Exponential"
	default:
		return string(e)
	}
}

// Config holds retry configuration. InitialDelay and MaxDelay are
// datetime.Duration values (transparent aliases of time.Duration) — write
// `500 * time.Millisecond`, not bare ints.
type Config struct {
	MaxAttempts    int
	InitialDelay   datetime.Duration
	MaxDelay       datetime.Duration
	JitterFraction float64
	Strategy       Strategy
}

// New creates a default retry configuration: 3 attempts, 1s initial delay, exponential backoff
// Example: cfg := retry.New()
func New() Config {
	return Config{MaxAttempts: 3, InitialDelay: time.Second, Strategy: StrategyExponential}
}

// Attempts sets the maximum number of retry attempts
// Example: cfg := retry.New() |> retry.Attempts(5)
func Attempts(cfg Config, maxAttempts int) Config {
	cfg.MaxAttempts = maxAttempts
	return cfg
}

// Delay sets the initial delay between attempts. Exponential doubles it
// each attempt; Linear reuses it.
// Example: cfg := retry.New() |> retry.Delay(500 * time.Millisecond)
func Delay(cfg Config, d datetime.Duration) Config {
	cfg.InitialDelay = d
	return cfg
}

// MaxDelay caps the computed delay between attempts. Exponential growth is
// unbounded without it — 10 attempts at a 1s initial delay sleeps 512s on
// the last gap. Zero (the default) means uncapped.
// Example: cfg := retry.New() |> retry.MaxDelay(30 * time.Second)
func MaxDelay(cfg Config, d datetime.Duration) Config {
	cfg.MaxDelay = d
	return cfg
}

// Jitter randomizes each sleep within ±fraction of the computed delay, so
// many clients retrying the same endpoint don't re-synchronize (thundering
// herd). fraction is clamped to [0, 1]; 0.1–0.2 is a common choice.
// Example: cfg := retry.New() |> retry.Jitter(0.2)
func Jitter(cfg Config, fraction float64) Config {
	cfg.JitterFraction = math.Clamp(fraction, 0.0, 1.0)
	return cfg
}

// Linear switches to a fixed-delay backoff strategy
// Example: cfg := retry.New() |> retry.Linear() |> retry.Delay(1 * time.Second)
func Linear(cfg Config) Config {
	cfg.Strategy = StrategyLinear
	return cfg
}

// Exponential switches to an exponential backoff strategy (the default)
// Example: cfg := retry.New() |> retry.Exponential() |> retry.Attempts(5) |> retry.Delay(500 * time.Millisecond)
func Exponential(cfg Config) Config {
	cfg.Strategy = StrategyExponential
	return cfg
}

// Do runs fn with retries according to cfg, stopping on the first success.
// Returns the last error if every attempt fails. fn is called at least once
// even if cfg.MaxAttempts is 0, so callers always get one shot.
func Do(cfg Config, fn func() error) error {
	attempts := max(cfg.MaxAttempts, 1)
	for attempt := range attempts - 1 {
		err := fn()
		if err == nil {
			return nil
		}
		Sleep(cfg, attempt)
	}
	return fn()
}

// DoCtx runs fn with retries according to cfg, stopping on the first success
// or when the context is cancelled. fn is passed the context handle.
// The handle type is inferred, so inline lambdas work without a named helper:
//
//	retry.DoCtx(ctx, cfg, (h) =>
//	    _, err := fetch.GetCtx(h, url)
//	    return err
//	)
func DoCtx(h ctxpkg.Handle, cfg Config, fn func(ctxpkg.Handle) error) error {
	attempts := max(cfg.MaxAttempts, 1)
	for attempt := range attempts - 1 {
		if h.Ctx.Err() != nil {
			return h.Ctx.Err()
		}
		err := fn(h)
		if err == nil {
			return nil
		}
		Sleep(cfg, attempt)
	}
	return fn(h)
}

// Sleep pauses execution for the delay appropriate to the given attempt number.
// The delay is cfg.InitialDelay (doubled per attempt under Exponential),
// capped by cfg.MaxDelay, then widened by cfg.JitterFraction.
// Call this between retry attempts; attempt is zero-indexed.
func Sleep(cfg Config, attempt int) {
	time.Sleep(calculateDelay(cfg, attempt))
}

// maxDuration is the largest expressible datetime.Duration — the saturation
// point for unbounded exponential growth.
const maxDuration datetime.Duration = 9223372036854775807

// halfMaxDuration is maxDuration / 2; doubling anything larger overflows.
const halfMaxDuration datetime.Duration = 4611686018427387903

// calculateDelay returns the delay before the given zero-indexed attempt:
// InitialDelay doubled per attempt under Exponential (saturating instead of
// overflowing int64 nanoseconds), capped by MaxDelay, then widened by
// JitterFraction.
func calculateDelay(cfg Config, attempt int) datetime.Duration {
	delay := cfg.InitialDelay
	if cfg.Strategy == StrategyExponential {
		for range attempt {
			if delay > halfMaxDuration {
				delay = maxDuration
				break
			}
			delay = delay * datetime.Duration(2)
		}
	}
	if cfg.MaxDelay > 0 && delay > cfg.MaxDelay {
		delay = cfg.MaxDelay
	}
	if cfg.JitterFraction > 0.0 {
		offset := random.Float(-cfg.JitterFraction, cfg.JitterFraction)
		delay = datetime.Duration(float64(delay) * (1 + offset))
	}
	return delay
}
